use gielinor_client::{disk_cache::DiskCache,item::Definitions,item_icon::{Icons,Options},raster::Raster,font::{Font,Style}};
fn main()->Result<(),Box<dyn std::error::Error>>{let a=std::env::args().collect::<Vec<_>>();let mut cache=DiskCache::open(&a[1],64<<20)?;let defs=Definitions::load(&mut cache)?;let mut icons=Icons::load(&mut cache,0.8)?;let font=Font::load(&mut cache,494)?;let mut raster=Raster::new(720,560,1<<20)?;raster.clear(0xff29251f);
 let ids=[995,4151,4152,11802,11803,1215,1231,1333,1334,1127,1128,1050,1163,1185,1079,3105,385,386,314,554,555,556,557,558,559,560,561,562,563,564,565,566,1511,1512,1513,1514,227,228,229,230,2434,2440,1265,1275,1351,1359,590,946,1733,1755,1947,1925,5600,11840,6570,6585,19564,19565,20405,20406,13190,13204,23490,22981];
 for (i,id) in ids.into_iter().enumerate(){let x=(i%8) as i32*90+25;let y=(i/8) as i32*68+10;let sprite=icons.get(&mut cache,&defs,id,Options{quantity:if id==995{12500000}else{1},outline:2,shadow:0x302020,..Options::default()})?;sprite.draw(&mut raster,x,y,256)?;font.draw(&mut raster,&id.to_string(),x,y+45,Style::default(),&[])?;}
 std::fs::write(&a[2],raster.bmp()?)?;println!("Rendered 64 item icons natively");Ok(())}
